func (v CveContents) trivyTypes() CveContentTypes {
	types := CveContentTypes(GetCveContentTypes("trivy"))
	known := make(map[CveContentType]struct{}, len(types))
	for _, ctype := range types {
		known[ctype] = struct{}{}
	}
	var additional CveContentTypes
	for ctype := range v {
		if _, found := known[ctype]; !found && strings.HasPrefix(string(ctype), "trivy:") {
			additional = append(additional, ctype)
		}
	}
	sort.Slice(additional, func(i, j int) bool { return additional[i] < additional[j] })
	return append(types, additional...)
}

